        if self.SIGNER_PUBLIC_KEY is not None:
            RPCAddSIGNER_PUBLIC_KEY(builder, SIGNER_PUBLIC_KEY)
        if self.SIGNATURE_TYPE is not None:
            RPCAddSIGNATURE_TYPE(builder, SIGNATURE_TYPE)
        if self.SIGNATURE is not None:
            RPCAddSIGNATURE(builder, SIGNATURE)
        if self.CANONICAL_JSON_SIGNATURE is not None:
            RPCAddCANONICAL_JSON_SIGNATURE(builder, CANONICAL_JSON_SIGNATURE)
        RPC = RPCEnd(builder)
        return RPC
